pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: dominant reward
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead: exact match with next item is highly valuable
    let nis = next_item_size as f64;
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 470.0;
        } else if post_residual >= next_item_size {
            let next_post = pr - nis;
            score -= 75.0 * (1.0 - next_post / cap);
            if next_post < 12.0 {
                score += 15.0;
            }
            if next_post == 0.0 {
                score -= 45.0;
            }
            // two-step lookahead
            if next_post >= 2.0 * nis {
                score -= 7.0 * (1.0 - next_post / (2.0 * cap));
            }
        } else {
            // next item won't fit: penalize stranded residual
            score += 0.65 * (nis - pr).min(25.0);
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 24.0 * (1.0 - progress);
        }
    }

    // Dead space relative to next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.0 * pr;
    }

    // Capacity-fraction classes of the residual
    let frac = pr / cap;
    if frac > 0.5 {
        score -= 5.0;
    } else if frac < 0.2 {
        score += 10.0;
    }

    // Last-chance bin: prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size.max(1) {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 11.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when it avoids dead space
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 11.0 * (1.0 - fill_ratio);
        if post_residual < 10 {
            score += 15.0;
        }
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        score += 18.0
            - (open_bins_count as f64 * 1.5)
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Slight preference for tighter bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Dispersion normalization
    score += 0.3 * (mean_residual - pr) / cap;
    if (bin_residual as f64 - mean_residual).abs() > 40.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are heavily penalized dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it would fit exactly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0;
    }
    // Penalize if post_residual cannot fit the next item but is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when current bins have bad fits
    // (small residuals) or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let bad_open_bins = open_bins_count as f64 * (mean_residual < 15.0) as i32 as f64;
        score = 100.0 - bad_open_bins * 10.0 + item_size as f64 * 0.2;
        if fitting_bins_count == 1 {
            score += 50.0; // prefer using the last fitting bin over opening new
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward if the next item fits exactly or at all.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            // reward proportionally to how much slack remains for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 40.0;
        }
    }

    // Penalize small unusable gaps (< 10, minimum item size) harder.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0;
    }

    // Late in the stream: consolidate, prefer filling existing bins over opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 10.0 + 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, dead space is costlier.
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth interaction: reward post_residual that matches the next item size
    // (good residual = near but >= next item), via a smooth bump.
    if nxt > 0.0 {
        let diff = (pr - nxt) / cap;
        score -= 3.0 * (-diff * diff * 40.0).exp() * (1.0 - progress * 0.5);
    }

    // Penalize tiny unusable residuals with a smooth rational term.
    score += 4.0 / (1.0 + pr * pr / 25.0) * (1.0 - progress * 0.3);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 2.5 * last_chance * (0.5 + 0.5 * progress);

    // Slight pull toward bins with residuals below the mean (compactness pressure).
    score += 0.3 * ((pr as f64 - mean_residual) / cap);

    // Mild penalty on bin proliferation early in the stream.
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, prefer tight fits (small post residual); later, tolerate slack
    // to keep bins usable for remaining items.
    let w = 0.6 + 1.4 * progress * progress;
    score += w * (x * x * x) * cap;

    // Penalize dead space that cannot fit the next item (smooth quadratic gate).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - post) / cap).max(0.0);
        score += 25.0 * unusable * unusable * cap;
    }

    // Reward being the unique fitting bin (last chance before a new bin).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference for bins already below average residual (consolidation),
    // smoothed with a cubic of the difference.
    let d = (mean_residual - post) / cap;
    score += 8.0 * d * d * d;

    // Smooth new-bin penalty: opening a bin early is costly, less so late.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Slight nudge toward fuller bins overall (cubic in fill fraction).
    let fill = (cap - post) / cap;
    score -= 10.0 * fill * fill * fill;

    score
}

