pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr;

    // Stream-progress coupling: tighten residual tolerance as stream advances
    let tightness = 1.0 + 1.5 * progress;
    score *= tightness;

    // Interaction: post residual vs mean residual — reward bins tighter than average
    score -= 8.0 * (mean_residual - pr) / cap * (1.0 + progress);

    // Perfect fit bonus (smooth)
    score -= 30.0 * (1.0 - norm_pr).powi(6);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post residual can't fit next item, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = pr >= nxt;
        let smooth = (pr - nxt + 1.0).max(0.0) / cap;
        if fits_next {
            score -= 10.0 * smooth;
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for many open bins to discourage bin proliferation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in
    // "useful" residue classes should be rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual too small to host even the smallest item.
    if post_residual < 10u32.min(bin_capacity) {
        score += 60.0;
    }

    // Harmonic class reward: post_residual divisible by common item sizes
    // (e.g. multiples of 10/20/25/50) is reusable dead-space-light.
    let classes: [u32; 6] = [10, 20, 25, 40, 50, 100];
    let mut harmonic_bonus = 0.0;
    for c in classes.iter() {
        if *c <= bin_capacity && post_residual % c == 0 && post_residual > 0 {
            harmonic_bonus += 8.0;
        }
    }
    score -= harmonic_bonus;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize large wasted residual relative to capacity (fractional waste).
    let waste_frac = pr / cap;
    score += 25.0 * waste_frac * waste_frac;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += 6.0 * (1.0 - (next_item_size as f64 - pr) / cap).max(0.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate bias: opening a new bin is only attractive when the
    // item is large and mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let pressure = mean_residual / cap;
        // penalize new bin when open bins are roomy; reward when tight
        score += 30.0 * pressure - 20.0 * item_frac;
    }

    // Stream progression: later in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * waste_frac;

    // Tie-break by residual distance to mean (prefer typical bins slightly).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual that is too small for the smallest plausible item is "dead space".
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Dead space penalty: quadratic in how close we are to a sliver.
        score += (11.0 - post_residual as f64) * 30.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Penalize large leftover only mildly; large residual is reusable.
    // But penalize residual that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residuals that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open-bins pressure: prefer bins that keep the number of open bins low,
    // but only when the fit is decent. Scale with stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): discourage unless it produces a useful
    // large residual and existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 90.0;
        // If the item nearly fills the fresh bin, opening is attractive.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 100.0;
        }
        // If no real bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild bonus for bins tighter than the current mean residual (good density).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

