pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for large leftover.
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has high raw score (post_residual
    // = capacity); only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when existing residuals are generous.
        score += 70.0 * (1.0 - crowding);
        // Early in the stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        // If many bins fit the item, discourage opening a new one.
        score += 10.0 * (fitting_bins_count as f64);
    } else {
        // Prefer bins with residual far below mean (use up fragmented space).
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild preference for bins among many open bins to consolidate.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr + (pr * pr) / (2.0 * cap);

    // Non-linear coupling of post-residual with stream progress:
    // late in stream, dead space is more costly; early, exact fits matter less
    let progress_term = progress * (1.0 - progress) * 4.0; // peak mid-stream
    score += progress_term * (pr * pr) / cap;

    // Reward tight fits relative to bin residual (smooth saturation)
    let fill_ratio = 1.0 - (pr / br.max(1.0));
    score -= fill_ratio * fill_ratio * it * 0.5;

    // Last-chance bonus: if only this bin fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.5 * pr;
    }

    // Penalize bins whose post-residual can't fit the next item when lookahead exists
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += gap * (0.5 + 2.0 * progress);
        } else {
            // smooth reward when next item fits exactly-ish
            score -= 3.0 * (1.0 + gap.abs() / cap);
        }
    }

    // Mild penalty proportional to how far this bin's residual deviates from mean residual
    let dev = (br - mean_residual).abs();
    score += 0.05 * dev * (0.5 + progress);

    // Slight preference for using existing bins over opening new ones, stronger late
    if bin_residual as u32 == bin_capacity as u32 {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that is too small to hold even the
    // smallest plausible item is nearly worthless. Classify post_residual
    // into harmonic classes via integer division thresholds.
    let dead = post_residual < 10;
    let tiny = post_residual < 20 && !dead;
    let small = post_residual < 35 && !dead && !tiny;
    if dead {
        score += 0.0; // perfect closure, best possible outcome
    } else if tiny {
        score += 6.0;
    } else if small {
        score += 12.0;
    }

    // Harmonic class: bucket post_residual by quarters of capacity.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    // Non-linear coupling: mid classes (residual ~25-50) are the hardest
    // to fill later; penalize them slightly more.
    if class == 1 {
        score += 4.0;
    } else if class == 2 {
        score += 2.5;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 + 3.0 * (slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // This bin becomes dead space for the next item: penalize.
        score += 8.0;
    }

    // Exact-fit bonus: post_residual divisible cleanly (harmonic residue 0).
    if post_residual % 25 == 0 {
        score -= 2.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a marginal gain.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // every open bin. Make the empty-bin candidate unattractive unless the
    // item fits terribly everywhere (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 25.0 + 10.0 * pressure;
        // Late in the stream, opening bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is huge, a fresh bin preserves flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for consolidating into emptier bins when many are open.
    if open_bins_count > 4 {
        let norm = bin_residual as f64 / bin_capacity as f64;
        score += 2.0 * norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: gaps too small for the minimum item size (1)
    // are only bad if they cannot hold the *next* item; penalize small nonzero
    // gaps that are unusable relative to what is coming.
    if post_residual > 0 {
        let usable = if next_item_size > 0 { post_residual >= next_item_size } else { true };
        if !usable {
            // Dead space: gap smaller than the lookahead item.
            score += 60.0 + 0.5 * post_residual as f64;
        } else {
            // Usable gap: mild reward proportional to tightness of fit.
            score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Tight fit reward: how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Open-bins pressure: discourage spreading across many bins when few
    // alternatives exist; encourage using this bin when it is nearly alone.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: make it attractive only when the item is large
    // relative to typical open residuals or fits would be poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when justified.
        score += 45.0;
        // Large items start fresh bins more readily.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If the mean residual across open bins is small, a fresh bin helps.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 25.0 * progress;
    }

    // Lookahead coupling: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 90.0;
    }
    // Penalize leaving a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 3 {
        score += 15.0;
    }

    // Mild preference for bins with residuals near the item size (best fit flavor).
    score += 0.2 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post-residual exactly matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 == next {
            score -= 300.0; // perfect 2-step chain
        } else if post_residual as i64 >= next_item_size as i64 {
            score -= 150.0 / (1.0 + diff / 20.0); // next item still fits
        } else {
            // next item will NOT fit: penalize dead space relative to next size
            score += 60.0 + (next - post_residual as f64) * 0.8;
        }
    }

    // Penalize small unusable residuals (dead space below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with less residual (tighter bins) when fitting bins are scarce.
    if bin_residual as f64 > mean_residual {
        score += 0.35 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin leaves very poor fit
    // (large post_residual relative to capacity) or no open bin is a good host.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 250.0 - 200.0 * waste;
        if open_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Late in the stream: tighten packing, avoid leftover fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio;

    // Perfect / near-perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: small leftover slivers that nothing (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (which wastes the residual entirely).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a new bin, decaying over time when many bins are open.
        let mut open_cost = 30.0 - 10.0 * progress;
        // If existing bins are fragmented (high mean residual but poor fit), new bin is better.
        if mean_residual > 1.5 * item_size as f64 {
            open_cost -= 12.0;
        }
        // Large items start fresh bins happily.
        if item_size >= 60 {
            open_cost -= 8.0;
        }
        // If item barely fits elsewhere (post_residual tiny), discourage new bin.
        if post_residual == bin_capacity - item_size && post_residual < 15 {
            open_cost += 20.0;
        }
        score += open_cost;
    }

    // Slight preference for bins with above-average residual when item is small.
    if item_size <= 30 && (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear coupling: residual waste weighted by stream progress.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) via smooth term.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Penalize new-bin candidate smoothly: empty bin has bin_residual == bin_capacity.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 30.0 + 20.0 * (1.0 - progress);
        // But if no other bin fits, allow opening (smooth fallback).
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    // Last-chance bin reward: keep dead space from spreading.
    if fitting_bins_count == 1 && !is_new {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        let fits_next = post >= next_item_size as f64;
        if fits_next {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Mild pressure to consolidate into bins with larger residuals.
    score -= 5.0 * (bin_residual as f64 / cap) * (1.0 - progress);

    // Smooth open-bin count damping to avoid bin explosion late in stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Dead-space classes: leftover <= 10 is "perfect-ish", 11..=20 is good,
    // 21..=35 is mediocre, > 35 is wasteful (unlikely to be filled).
    let class_penalty = if post_residual == 0 {
        -60.0 // perfect fill
    } else if post_residual <= 10 {
        -45.0
    } else if post_residual <= 20 {
        -25.0
    } else if post_residual <= 35 {
        0.0
    } else {
        (frac * 40.0) // wasteful dead space, penalize proportionally
    };
    score += class_penalty;

    // Modulo harmonic: leftover that is itself a "usable" item size (10..=80 range,
    // here generalized 1..=100) is more likely to be consumed later.
    if post_residual >= 1 && post_residual <= 100 {
        score -= 12.0;
    }
    // Leftover in coarse harmonic classes (multiples of 10) aligns with typical sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: does the next item fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // exact follow-up fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: leftover must serve future items; mildly penalize
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin's leftover is very poor
    // and no tight fit exists. Penalize opening new bins when open bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_exists = next_item_size > 0 && next_item_size <= post_residual;
        let bad_fit = post_residual > 35 && !tight_exists;
        if bad_fit {
            score -= 10.0 + 15.0 * frac;
        } else {
            score += 25.0 + 40.0 * (1.0 - progress) * (open_bins_count as f64).sqrt().recip().min(1.0);
        }
    }

    // Prefer filling bins with larger residual when mean residual is high (spread usage),
    // and tighter bins when mean residual is low (consolidate).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest future item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Residuals too small for the lookahead item are semi-dead when the
    // next item cannot use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly via residual tie-break),
    // but with few bins, consolidation is fine.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. mean residual is small or item barely fits anywhere.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        score += 15.0 + 0.3 * spread.max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps room for lookahead
        }
    }

    // Mild preference for bins whose residual exceeds item + next item
    // (allows chaining two items).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space) with a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + 5.0 * (5 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect two-item chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward chains that keep the bin tight after two placements.
            score -= 60.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            // Penalize leaving awkward slivers the next item barely fits into.
            if next_post < 10 {
                score += 15.0;
            }
        } else {
            // Next item cannot continue in this bin; penalize proportionally
            // to how much dead space is stranded.
            let stranded = post_residual as f64;
            if stranded < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - stranded).min(20.0);
            }
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Mild penalty when many bins are open — encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Slight preference for opening fresh bins early in the stream when the
    // current fit is poor (post_residual large relative to next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize proportionally to leftover waste.
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (exploration).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more later in the stream (consolidate late).
        score += 10.0 + 40.0 * progress;
        // But if current bin would leave a bad fit and next item is large, allow new bin.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 12.0;
        }
    } else {
        // Open bins: slight reward when many bins open (encourage filling them).
        score -= 0.2 * open_bins_count as f64;
    }

    // Global state coupling: if mean residual is high, prefer bins below mean (balance).
    if (bin_residual as f64) > mean_residual {
        score += 0.4 * ((bin_residual as f64) - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, dead space is costlier.
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth interaction: reward post_residual that matches the next item size
    // (good residual = near but >= next item), via a smooth bump.
    if nxt > 0.0 {
        let diff = (pr - nxt) / cap;
        score -= 3.0 * (-diff * diff * 40.0).exp() * (1.0 - progress * 0.5);
    }

    // Penalize tiny unusable residuals with a smooth rational term.
    score += 4.0 / (1.0 + pr * pr / 25.0) * (1.0 - progress * 0.3);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 2.5 * last_chance * (0.5 + 0.5 * progress);

    // Slight pull toward bins with residuals below the mean (compactness pressure).
    score += 0.3 * ((pr as f64 - mean_residual) / cap);

    // Mild penalty on bin proliferation early in the stream.
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: classify post_residual into
    // coarse "harmonic" buckets via integer division on capacity fractions.
    let class = post_residual / 10; // 0..=10 harmonic class
    // Reward small residuals (tight fits), but with a floor so class 0 isn't
    // over-favored vs class 1 (dead space of 0 is fine, 1-9 is wasted too).
    score -= (class as f64) * 2.5;

    // Penalize residuals in the "unusable middle band" (11..=19): too large
    // to be dead, too small to fit most items reliably.
    if post_residual >= 11 && post_residual <= 19 {
        score += 14.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: this placement chains into the next item.
            score -= 18.0;
            // Extra reward if next item exactly matches the class boundary.
            if post_residual % next_item_size == 0 && post_residual > 0 {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item would have fit if we placed differently here: mild penalty
            // proportional to how much we "waste" the compatibility.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Mild early-stream aversion to hoarding bins; slight late-stream bonus
        // since residual fragmentation matters more as stream ends.
        score += 30.0 - 10.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
        // If the next item is large and this item is small, a fresh bin keeps
        // big-item capacity alive: small reward.
        if next_item_size > 60 && item_size < 30 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidating fullness).
    let mean_r = mean_residual;
    if (bin_residual as f64) < mean_r - 1.0 {
        score -= 4.0;
    } else if (bin_residual as f64) > mean_r + 1.0 {
        score += 3.0;
    }

    // Exact-fit celebration.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small noise-free tiebreak on bin index proxy: prefer earlier (fuller) bins
    // via open_bins_count pressure to close bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // smaller gap => worse
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is always excellent
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins,
    // but encourage using existing bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 20.0; // sets up a near-perfect follow-up
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // next item can't use this gap
    }

    // New-bin candidate handling: make a fresh bin moderately attractive
    // only when the current bin would leave bad dead space or nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit || (fitting_bins_count == 0) {
            score -= 45.0; // opening a new bin beats ruining a bin
        } else {
            score += 35.0; // prefer existing bins otherwise
        }
    }

    // Mild stream-phase modulation: early on, be a bit more willing to open bins.
    let phase = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - phase);
    }

    // Slight nudge toward bins with below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end with (near) zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: reward when the next item exactly fits the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain of two perfect fills
        } else if next_item_size < post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            // Penalize leaving a gap that the next item only partially fills,
            // scaled by how tight the partial fill is.
            score += 0.5 * lookahead_waste;
            if lookahead_waste < 10.0 {
                score -= 50.0; // near-chain: next item almost fills the remainder
            }
        } else {
            // Next item cannot fit in this bin after placement: the residual
            // becomes dead space at least until later items. Penalize small
            // unusable gaps (dead space) but tolerate large residuals that
            // future items may still use.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.8 * (next_item_size as f64 - dead); // gap too small for lookahead
            }
            score += 0.1 * dead;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (tighter bins) so loose bins stay available for larger future items.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item is large and the next item is also large (a fresh bin
    // gives maximum flexibility), or when no open bin fits well.
    if bin_residual == bin_capacity {
        let fresh_penalty = 120.0;
        let large_now = item_size as f64 / bin_capacity as f64;
        let large_next = next_item_size as f64 / bin_capacity as f64;
        // Reward opening a new bin for big items with big lookahead.
        score = fresh_penalty - 150.0 * large_now * large_next;
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin anyway
        }
    }

    // Late in the stream, be more conservative: avoid opening new bins and
    // squeeze into existing residual capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    } else {
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize wasted residual (dead space), with a super-linear kick.
    if post_residual < item_size {
        score += (post_residual as f64).powf(1.6) * 0.35;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 22.0;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // If next item nearly fits (small gap), mild reward.
    if next_item_size > post_residual && next_item_size > 0 {
        let gap = next_item_size as f64 - post_residual as f64;
        score += gap * 0.4;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize unless
    // current bin would be left with unusable crumbs or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 45.0 - 25.0 * progress;
        // If no open bin fits, opening is necessary.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 60.0;
        }
        // Big items leave less room for fragmentation; slightly favor fresh bins for them.
        new_bin_penalty -= 0.15 * item_size as f64;
        score += new_bin_penalty.max(-70.0);
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins (avoid bin sprawl).
    if open_bins_count > 2 {
        score += 0.6 * open_bins_count as f64;
        score += 0.3 * (mean_residual - post_residual as f64).abs();
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_weight = 0.5 + 0.9 * progress * progress - 0.2 * progress;
    let mut score = pr * progress_weight;

    // Non-linear penalty for dead space (small residuals are hard to fill)
    let dead = (1.0 - norm_pr).max(0.0);
    score += 12.0 * dead * dead * norm_pr;

    // Tight fits rewarded more strongly later in the stream
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 18.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 6.0 * ((next_item_size as f64 - pr) / cap);
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 14.0 - 16.0 * big * big;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are ideal; residuals in
    // "useless" classes (very small, or in awkward modular bands) are penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += 25.0; // dead space, nothing can ever fit
    } else if pr % 10 == 0 {
        score -= 12.0; // decadal residual: harmonizes with 10-multiple items
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Integer-division thresholds: how many "average future items" fit?
    let avg_next = if next_item_size > 0 { next_item_size } else { 45 };
    let fits_of_next = pr / avg_next.max(1);
    score -= fits_of_next as f64 * 8.0;

    // Lookahead coupling: does this placement leave room for the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.15;
        } else {
            score += 8.0; // next item won't fit here
        }
        // harmonic pair: post_residual exactly matches next item size class
        if pr == next_item_size {
            score -= 14.0;
        }
    }

    // Capacity-fraction classes of the residual
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0;
    } else if frac < 0.2 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave dead space
    if bin_residual == bin_capacity {
        let waste_penalty = if pr < 10 { 15.0 } else { 0.0 };
        score += 18.0 + waste_penalty
            - (open_bins_count as f64 * 1.5)
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Slight preference for tighter (fuller) bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild dispersion normalization
    if (bin_residual as f64 - mean_residual).abs() > 40.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
