    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 5 {
        // Near-perfect gaps are valuable: reward small leftovers.
        score -= 60.0 + 6.0 * (5 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // 2-step lookahead with next-item chaining.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 450.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            let next_post = (post_residual - next_item_size) as f64;
            score -= 70.0 * (1.0 - next_post / cap);
            if next_post == 0 {
                score -= 40.0;
            } else if next_post < 12 {
                score += 15.0; // avoid creating tiny dead gaps via next item
            }
            // Two-step reuse: leftover after next item can host another item
            if next_post >= 2.0 * nis {
                score -= 6.0 * (1.0 - next_post / (2.0 * cap));
            }
        } else {
            // next item cannot use leftover: penalize stranded space proportionally
            let stranded = (nis - pr).min(25.0);
            score += 0.6 * stranded + 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - pr);
    score += 0.3 * ((pr - mean_residual) / cap);

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0 * (1.0 - progress);
    }
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 * (1.0 - progress);
    }

