        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: residual is likely dead space.
        score += 8.0;
    }

    // Progress pressure: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

