pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual penalized more strongly
    // as the stream progresses (waste matters more later).
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // in [0,1)
    let progress_weight = 0.5 + 2.0 * progress * progress; // grows quadratically with progress
    score += progress_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits: subtract a smooth bump when post_residual is small.
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    score -= 8.0 * tightness * tightness * tightness * (1.0 + progress);

    // Penalize dead space that can't fit the next item (smooth logistic gate).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            let unusable = gap / cap;
            let gate = 1.0 / (1.0 + (-6.0 * unusable).exp());
            score += 12.0 * gate * unusable * cap * 0.1;
        } else {
            // Next item fits comfortably: mild smooth reward.
            let fit_margin = (-gap) / cap;
            score -= 4.0 * fit_margin * (1.0 - fit_margin) * (1.0 + progress);
        }
    }

    // Last-chance bin bonus: strongly favor using a nearly-unique fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to prefer consolidation elsewhere.
        score += 1.5 * ((fitting_bins_count - 2) as f64).ln();
    }

    // Mild pull toward bins near the mean residual (smooth centering).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Encourage opening new bins only when current bins are quite full:
    // smooth reward for new-bin candidate proportional to average fullness.
    if bin_residual == bin_capacity {
        let fullness = 1.0 - mean_residual / cap;
        score -= 3.0 * fullness * fullness * (1.0 + progress) - 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: quadratic coupling of post_residual with stream progress.
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Exact-fill dominance: empty post_residual is always best.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 60.0 + 6.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Smooth interaction: reward post_residual that matches the next item size.
    if nxt > 0.0 {
        let diff = (pr - nxt) / cap;
        score -= 3.0 * (-diff * diff * 40.0).exp() * (1.0 - progress * 0.5);
        // Exact match for the next item is a big win.
        if post_residual as u32 == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let next_post = pr - nxt;
            score -= 60.0 * (1.0 - next_post / cap);
            if next_post < 12.0 {
                score += 12.0;
            }
            if next_post == 0.0 {
                score -= 40.0;
            }
            // Two-step lookahead: residual can host next item twice.
            if next_post >= 2.0 * nxt {
                score -= 7.0 * (1.0 - next_post / (2.0 * cap));
            }
        } else {
            // Stranded residual smaller than next item: penalize more early.
            score += 0.65 * (nxt - pr).min(25.0) + 18.0 * (1.0 - progress);
        }
    }

    // Penalize tiny unusable residuals with a smooth rational term.
    score += 4.0 / (1.0 + pr * pr / 25.0) * (1.0 - progress * 0.3);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 2.5 * last_chance * (0.5 + 0.5 * progress);

    // Slight pull toward bins with residuals below the mean (compactness pressure).
    score += 0.3 * ((pr - mean_residual) / cap);

    // Mild penalty on bin proliferation early in the stream.
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate control: opening a fresh bin is only attractive when
    // the item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item / cap;
        score += 8.0 * (1.0 - fill_ratio);
        if open_bins_count > 1 && item < nxt.max(1.0) {
            score += 6.0;
        }
        // Late in the stream, strongly discourage new bins.
        score += 10.0 * progress;
    }

    // Late-stage compaction: penalize leaving residual space when bins are many.
    if open_bins_count > 8 && post_residual > 0 {
        score += 4.0 * progress * norm_pr;
    }

    // Near-miss penalty: residual just below next item is nearly wasted.
    if nxt > 0.0 && pr > 0.0 && pr < nxt && (nxt - pr) <= 3.0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes (dead space) should be penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual (classes of size 10).
    let class = post_residual / 10; // 0..10
    match class {
        0 => score += 6.0,        // near-perfect fit -> strongly reward
        1 => score -= 2.0,        // good leftover, usable by small items
        2 | 3 => score -= 1.0,    // decent leftover
        7 | 8 => score += 2.0,    // wasteful large leftover
        _ => {}
    }

    // Modulo arithmetic: leftover that is congruent to common item sizes
    // (mod 10) is more likely to be filled exactly later.
    if post_residual > 0 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 1.5; // round leftover, likely reusable
        } else {
            score += 0.5 * (m as f64) / 10.0;
        }
    }

    // Capacity-fraction coupling: reward leaving exactly half or quarter.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == half { score -= 1.0; }
    if post_residual == quarter { score -= 0.5; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size < post_residual {
            score -= 2.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 1.0; // next item cannot use this leftover
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the fit is terrible (large post_residual makes base score win).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
    }

    // Stream progression: later in the stream, be greedier (prefer tight fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let nis = next_item_size as f64 ;
    let frac = pr / cap ;
    if frac > 0.5 { score -= 5.0 ; } else if frac < 0.2 { score += 10.0 ; }
    score += 0.3 * ((pr - mean_residual) / cap) ;
    if post_residual == 0 {
        score -= 1200.0 ;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64 ;
    } else if post_residual < 10 {
        score -= 14.0 ;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 470.0 ;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size ;
            score -= 75.0 * (1.0 - next_post as f64 / cap) ;
            if next_post < 12 { score += 15.0 ; }
            if next_post == 0 { score -= 45.0 ; }
        } else {
            let stranded = pr ;
            if stranded < nis { score += 0.65 * (nis - stranded).min(25.0) ; }
        }
    }
    let dev = mean_residual - pr ;
    score += 0.3 * dev ;
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let progress = step_index as f64 / total_items.max(1) as f64 ;
        score += 24.0 * (1.0 - progress) ;
    }
    if next_item_size > 0 {
        if pr >= nis {
            score -= 13.0 + (pr - nis) * 0.2 ;
        } else {
            score += 8.0 ;
        }
        if pr == nis { score -= 18.0 ; }
    }
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap ;
        score -= 11.0 * (1.0 - fill_ratio) ;
        if open_bins_count > 1 && item_size < next_item_size.max(1) { score += 6.0 ; }
        let progress = step_index as f64 / total_items.max(1) as f64 ;
        score += 10.0 + 60.0 * progress ;
    }
    let dead = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { post_residual as f64 } else { 0.0 } ;
    score += 1.0 * dead ;
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let reuse = (post_residual - next_item_size) as f64 / cap ;
        score -= 5.5 * (1.0 - reuse) ;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_post = (post_residual - next_item_size) as f64 ;
        if nxt_post >= nis * 0.5 && nxt_post >= 10.0 {
            score -= 9.0 * (1.0 - nxt_post / cap) ;
        }
        if nxt_post >= 2.0 * nis {
            score -= 7.0 * (1.0 - nxt_post / (2.0 * cap)) ;
        }
    }
    if next_item_size > 0 && post_residual > 0 {
        let gap = nis - pr ;
        if gap > 0.0 && gap <= 14.0 { score += 0.55 * gap ; }
    }
    if open_bins_count > 8 && post_residual > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64 ;
        score += 4.0 * progress * (pr / cap) ;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size.max(1) {
        let progress = step_index as f64 / total_items.max(1) as f64 ;
        score += 11.0 * (1.0 - progress) ;
    }
    if next_item_size == 0 && post_residual > 0 {
        score += 3.0 * (pr / cap) ;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 3 {
        score += 20.0 ;
    }
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 120.0 ; }
    score += 0.3 * open_bins_count as f64 ;
    let score = score * 0.70 + pr * 0.30 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if frac > 0.5 { score -= 5.0 ; } else if frac < 0.2 { score += 10.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are worthless "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver — strong penalty
    }
    // "Awkward zone": residual too small for the next item but not zero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small but usable post_residual).
    if post_residual > 0 && post_residual >= 10 {
        score -= 8.0;
    }

    // Last usable bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 && bin_residual < bin_capacity {
        // Mild preference to fill existing bins when alternatives exist.
        score -= 5.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // and when post_residual of this fresh bin would be large.
        score += 40.0 + 10.0 * pressure + 15.0 * progress;
        // Allow a new bin only if the item is large relative to capacity
        // and would leave a very awkward residual elsewhere.
        if item_size as f64 > 0.9 * bin_capacity as f64 {
            score -= 55.0;
        }
    } else {
        // Existing bin: slight bonus proportional to how much it fills.
        score -= 2.0 * (item_size as f64 / bin_capacity as f64);
        // Prefer bins whose residual is close to mean (balanced packing),
        // discouraging extreme fragmentation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let nis = next_item_size as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let frac = pr / cap ;

    // primary compaction: prefer small post residual
    if post_residual == 0 {
        score -= 1200.0 ;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64 ;
    } else if post_residual < 10 {
        score -= 14.0 ;
    } else if frac < 0.2 {
        score += 10.0 ;
    } else if frac > 0.5 {
        score -= 5.0 ;
    }

    // lookahead: exact fit for next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0 ;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size ;
            score -= 75.0 * (1.0 - next_post / cap) ;
            if next_post == 0 {
                score -= 45.0 ;
            } else if next_post < 12 {
                score += 15.0 ;
            }
            if next_post >= 2.0 * nis {
                score -= 7.0 * (1.0 - next_post as f64 / (2.0 * cap)) ;
            }
        } else {
            let gap = nis - pr ;
            score += 0.65 * gap . min (25.0) ;
            if gap <= 3.0 {
                score += 20.0 ;
            }
        }
    }

    // deviation from mean residual
    score += 0.3 * (mean_residual - pr) ;

    // lone fitting bin: strong preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 130.0 ;
    }

    // mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 ;

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap ;
        score += 10.0 + 60.0 * progress ;
        score -= 11.0 * (1.0 - fill_ratio) ;
        if open_bins_count > 1 && next_item_size > 0 && item_size < next_item_size {
            score += 6.0 ;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0 * (1.0 - progress) ;
        }
    }

    // dead space penalty: residual too small for next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.0 * pr + 24.0 * (1.0 - progress) ;
        if fitting_bins_count <= 2 {
            score += 11.0 * (1.0 - progress) ;
        }
    }

    // late-stage: prefer filling fuller bins
    if open_bins_count > 8 && post_residual > 0 {
        score += 4.0 * progress * frac ;
    }

    // end of stream: just minimize residual
    if next_item_size == 0 && post_residual > 0 {
        score += 3.0 * frac ;
    }

    let score = score * 0.70 + pr * 0.30 ;
    if post_residual == 0 { score - 1000.0 } else { score }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let mut score = post_residual as f64;

    // Strong perfect-fit reward
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 4 {
        score -= 60.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score += 20.0; // dead space
    } else if post_residual % 10 == 0 {
        score -= 14.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead: room for next item, and quality of what remains after it
    if next_item_size > 0 {
        if pr >= nis {
            let next_post = post_residual - next_item_size;
            score -= 70.0 * (1.0 - next_post / cap);
            if next_post == 0 {
                score -= 40.0;
            } else if next_post < 12 {
                score += 12.0;
            }
            if next_post as f64 >= nis * 0.5 && next_post >= 10 {
                score -= 8.0 * (1.0 - next_post as f64 / cap);
            }
            if next_post as u32 >= 2 * next_item_size {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize by stranded amount
            score += 8.0 + 0.6 * (nis - pr).min(25.0);
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 20.0 * (1.0 - progress);
        }
        if pr == nis {
            score -= 350.0;
        }
