        if post_residual == next_item_size {
            score -= 470.0;
        } else if post_residual >= next_item_size {
            let next_post = pr - nis;
            score -= 75.0 * (1.0 - next_post / cap);
            if next_post < 12.0 {
                score += 15.0;
            }
            if next_post == 0.0 {
                score -= 45.0;
            }
