            if next_post >= 2.0 * nis {
                score -= 7.0 * (1.0 - next_post / (2.0 * cap));
            }
            // future fit quality: remainder big enough for another half-item
            if next_post as f64 >= nis * 0.5 && next_post >= 10.0 {
                score -= 9.0 * (1.0 - next_post / cap);
