    let frac = pr / cap;
    if frac > 0.5 {
        score -= 5.0;
    } else if frac < 0.2 {
        score += 10.0;
    }

    // Last-chance bin: prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size.max(1) {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 11.0 * (1.0 - progress);
    }

