    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 11.0 * (1.0 - fill_ratio);
        if post_residual < 10 {
            score += 15.0;
        }
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        // discourage new bins when an existing bin can still host the next item
        if next_item_size > 0 && item_size < next_item_size && pr >= nis {
