    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain: place here
        }
        // penalize leaving residual that neither fits next item nor is small
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Reward tight fits relative to current bin residual
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Compare against mean residual: prefer bins whose residual deviates below mean
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when an open bin gives a good fit
    if bin_residual == bin_capacity {
        score += 5.0 + (post_residual as f64 * 0.2);
        if fitting_bins_count > 0 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Slight preference to fill older/more-filled bins late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
