pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.9 * tightness * (bin_capacity as f64);

    // Exact fit: perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // placing here would break the next item's fit in this bin: mild penalty
            score += 4.0;
        }
        // dead space check: post_residual too small for any typical item
        if post_residual < 10 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open and reasonably full.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when mean residual across open bins is large
        score += 0.25 * mean_residual + 2.0 * (open_bins_count as f64).sqrt();
        // early stream: opening bins is cheap-ish; late stream: prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0) as f64;
        score += 15.0 * progress;
        if fitting_bins_count == 0 {
            // no open bin can fit: new bin is forced, remove penalty
            score -= 0.25 * mean_residual + 2.0 * (open_bins_count as f64).sqrt() + 15.0 * progress;
        }
    }

    // Slight preference for bins with residual below the mean (consolidating fullness).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Late-stream pressure: favor filling existing bins harder as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: quadratic term in normalized post_residual is damped;
    // late stream: quadratic penalty grows, favoring tight fits.
    let x = pr / cap; // normalized post residual in [0,1]
    let w = progress * progress; // smooth progress weight
    score += w * 40.0 * x * x + 10.0 * progress * x;

    // Cubic coupling: strongly punish mid-range dead space as stream progresses.
    score += 15.0 * w * x * x * x;

    // Reward near-perfect fits smoothly.
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: only one bin fits, prefer using it over opening new.
    if fitting_bins_count == 1 {
        score -= 6.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize leaving awkward residual.
        score += 3.0 * x * progress;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.5 * (pr - mean_residual) * (0.5 + progress);

    // Slight preference to reuse existing bins vs opening new ones early on.
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let mut score = post_residual as f64;

    // Strong perfect-fit reward
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 4 {
        score -= 60.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0; // small scraps are still usable (borrowed from best)
    } else if post_residual % 10 == 0 {
        score -= 14.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead: room for next item, and quality of what remains after it
    if next_item_size > 0 {
        if pr >= nis {
            let next_post = post_residual - next_item_size;
            score -= 75.0 * (1.0 - next_post / cap);
            if next_post == 0 {
                score -= 45.0;
            } else if next_post < 12 {
                score += 12.0;
            }
            if next_post as f64 >= nis * 0.5 && next_post >= 10 {
                score -= 9.0 * (1.0 - next_post as f64 / cap);
            }
            if next_post as u32 >= 2 * next_item_size {
                score -= 7.0 * (1.0 - next_post as f64 / (2.0 * cap));
            }
            // reward leaving a residue that matches common sizes (divisibility lookahead)
            if next_post % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize by stranded amount
            let gap = nis - pr;
            score += 8.0 + 0.6 * gap.min(25.0);
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 20.0 * (1.0 - progress);
            // near-miss: a small gap means this bin is almost done; mild penalty only
            if gap <= 14.0 {
                score += 0.55 * gap;
            }
        }
        if pr == nis {
            score -= 470.0;
        }
        if pr >= nis {
            score -= 13.0 + (pr - nis) * 0.2;
        }
    }

    // Capacity-fraction classes
    let frac = pr / cap;
    if frac > 0.5 {
        score -= 5.0;
    } else if frac < 0.2 {
        score += 10.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 11.0 * (1.0 - progress);
    }

    // Dead space penalty when next item cannot use the leftover
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.0 * pr;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 11.0 * (1.0 - fill_ratio);
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        if post_residual < 10 {
            score += 15.0;
        }
        score += open_bins_count as f64 * 1.2
            + (step_index as f64 / total_items.max(1) as f64) * 8.0;
    }

    // Prefer fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Dispersion normalization
    let dev = pr - mean_residual;
    score += 0.3 * dev / cap * cap;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    score
}

