pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for any item (min size 1..100 unknown, but small gaps are waste)
        score += (10.0 - pr) * 3.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // leaves exact room for lookahead item
    }

    // If next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 * 0.5 {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 2.0;

    // New-bin candidate: empty bin has high residual; penalize it unless
    // current bins are quite full (mean residual low) or fit is bad.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // opening a new bin is justified when existing bins are nearly full
        let justification = (mean_r / bin_capacity as f64).max(0.0);
        score += 60.0 - justification * 80.0;
        if item_size >= 50 {
            score -= 15.0; // big items fine in fresh bins
        }
    }

    // Prefer bins whose residual is close to item size (good packing density).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.3;

    // Mild preference toward bins with residual near mean (balanced depletion).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1200.0;
