            // Next item cannot use this leftover: penalize stranded space.
            let gap = nis - pr;
            score += 40.0 + 0.6 * gap.min(25.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - pr) * 0.5;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Opening a new bin is fine for large items; penalize for small items.
        score += 10.0 + 60.0 * progress - 12.0 * fill_ratio;
        // If the item is small and the next item is bigger, prefer keeping the
        // current bin for the next item: discourage opening a bin now.
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        // If many bins are already open, discourage adding more.
        if open_bins_count > 8 {
            score += 2.0 * (open_bins_count as f64 - 8.0).min(10.0);
        }
    }

    // Dead-space accounting: leftover that no future item can use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.0 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
