pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress_sq = progress * progress;
    let progress_mix = progress + 0.5 * progress_sq;

    // Base: tight fits are good (low post_residual lowers score), scaled by progress.
    let mut score = pr * (0.6 + 0.8 * progress_mix);

    // Smooth quadratic penalty on dead space: residuals that are too small to be useful.
    let dead_threshold = 0.35 - 0.15 * progress; // later in stream, tolerate less waste
    let deadness = (dead_threshold - norm_pr).max(0.0);
    score += 40.0 * deadness * deadness * cap;

    // Reward near-perfect fills with a smooth bump (cubic in normalized residual).
    let fill = 1.0 - norm_pr;
    score -= 25.0 * fill * fill * fill * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Many fitting bins: mild penalty to keep options open for future items.
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap).abs().min(1.0);
            score -= 15.0 * fit_quality * (1.0 - progress * 0.5);
        } else {
            // Smooth penalty for leaving residual that barely misses next item.
            score += 8.0 * (1.0 - (-gap / cap).min(1.0));
        }
    }

    // Interaction with mean residual: placing into a bin far from the mean smooths the pool.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * (1.0 - progress);

    // Mild pressure against opening many bins early.
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-eighth buckets; leftovers that are too small for the minimum
    // item are dead weight and must be penalized heavily.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold {
        score -= 60.0; // perfect or near-perfect fill: excellent
    } else {
        let eighth = cap / 8.0;
        let class = (post_residual as f64 / eighth).floor() as f64;
        // Larger harmonic class = more wasted space, superlinear penalty.
        score += class * class * 2.5;
    }

    // Harmonic compatibility with the lookahead item (k=2): if the next item
    // fits exactly in the post residual, reward strongly (modular pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Fractional complement: reward when next item leaves a small tail.
            let tail = post_residual - next_item_size;
            if tail < dead_threshold {
                score -= 30.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.3;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is, in capacity fractions.
            let frac = (next_item_size - post_residual) as f64 / cap;
            score += frac * 25.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Prefer tighter bins: closeness of item to residual (good fit) rewarded.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Avoid spreading across too many open bins when mean residual is low
    // (bins are nearly full already) — favor consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins unless current bins
        // are congested (low mean residual) or many bins fit poorly.
        score += 40.0
            + mean_residual * 0.2
            + (fitting_bins_count as f64) * -3.0
            + progress * 10.0;
        // Late stream with large items: new bin less painful.
        if item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin slightly reduces effective bin count pressure.
        score -= 5.0;
        // If many bins fit, prefer the one leaving the most useful residual
        // (residual close to a harmonic multiple of common sizes).
        if post_residual % 20 == 0 {
            score -= 8.0;
        } else if post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
