pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward using bins that are already fairly full (small residual before placement).
    let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_fraction;

    // Pressure from number of open bins: with many open bins, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.35 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 10.0;
    }
    // If next item almost fits but would be blocked, mild penalty.
    else if next_item_size > 0 && (post_residual as i64) > 0 && (next_item_size as u32) > post_residual && next_item_size <= bin_capacity {
        score += 3.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a good target.
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.15 * residual_diff;

    // New-bin candidate: keep it competitive only when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
        score += 10.0 + open_bins_count as f64 * 0.5 - bad_fit_penalty;
    }

    score
}

