pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Near-perfect tiny gaps: reward small leftovers (hard to reuse anyway).
    if post_residual > 0 && post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual > 0 && post_residual < 10 {
        score -= 14.0;
    }

    // 2-step lookahead with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 470.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 75.0 * (1.0 - next_post / cap);
            if next_post == 0 {
                score -= 45.0;
            } else if next_post < 12 {
                score += 15.0; // would strand a tiny gap after next item
            }
            // future usability of the residual after next item
            if next_post >= 10 && (next_post as f64) >= nis * 0.5 {
                score -= 9.0 * (1.0 - next_post as f64 / cap);
            }
        } else {
            // next item cannot use this bin's leftover: penalize stranded space
            let stranded = (nis - pr).min(25.0);
            score += 0.65 * stranded;
            let waste_ratio = (next_item_size - post_residual) as f64 / nis;
            score += 6.0 * waste_ratio * waste_ratio;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let dev = mean_residual - pr;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 11.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 11.0 * (1.0 - fill_ratio);
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0; // small item into fresh bin is wasteful
        }
        // late in stream: consolidate, discourage opening new bins
        score += 10.0 + 50.0 * progress;
    }

    score
}

