    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= 2.5 * (mean_residual - bin_res).min(50.0) / 50.0;
    } else {
        score += 1.5 * (bin_res - mean_residual).min(50.0) / 50.0;
    }

