    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Lookahead: penalize if next item could pair with this post_residual (good chain),
    // reward (lower score) when post_residual exactly matches next item.
