        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; dead space risk grows with small post_residual
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins with slack: discourage fragmenting; prefer consolidation.
    if open_bins_count > 3 {
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 0.5 * mean_gap;
        score += (open_bins_count as f64).ln() * 3.0;
    }

