        score += 8.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64 * 10.0;
    }

    // Early in stream: be more exploratory, tolerate new bins; late: consolidate hard.
    let new_bin_penalty = 40.0 + 200.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Exception: big item early with no good fit anywhere is fine in fresh bin
        if item_size > bin_capacity / 2 && progress < 0.3 {
            score -= 60.0;
        }
    }

    // Late stream: penalize leaving residuals that nothing (min size 1..10) can use
    if progress > 0.7 && post_residual > 0 && post_residual < item_size.min(20) {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
