pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item
    // granularity (gcd-style classes of 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reusability: does post_residual still admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
