    // half of the bin (dense fill), punish near-full-but-unusable zones.
    let frac = post / cap;
    if frac < 0.2 {
        score -= 4.0; // nearly closed bin: excellent
    } else if frac > 0.5 {
        score += 3.0 * frac; // half-empty: keep only if fit is tight
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 8.0 };
        score = cap * 0.75 + desperation + (open_bins_count as f64) * 0.5;
    }

    // Late in the stream: consolidate, avoid spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

