    }

    // Lookahead: if next item would fit exactly in the post residual, big reward
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 120.0;
    }

    // Mean residual coupling: bins far below mean residual are "wasted" space
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

