        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 55.0;
        }
    }

    // Mild stream-progress adaptation: later in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

