    let mut score = (post / cap).powi(2) * cap;

    // Smooth coupling with stream progress: late in the stream, waste is penalized more
    score += (post / cap).powi(3) * cap * progress;

    // Reward tight fits: subtract a smooth bonus when post-residual is small
    let tightness = 1.0 - post / cap;
    score -= tightness.powi(2) * item_size as f64;

