    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_ratio = next_item_size as f64 / post;
        score -= 10.0 * fit_ratio * (1.0 - progress);
    }

    // Penalize bins whose residual is far from mean residual (encourages residual homogenization)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (dev / cap) * (1.0 - post / cap) * 15.0;

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln() * (post / cap) * 2.0 * (0.5 + progress);

    // New-bin candidate handling: empty bin gets neutral base, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 0.1 * post;
