    let residue = post_residual % 10;
    score -= (10 - residue) as f64 * 0.7; // prefer post-residuals near a full class boundary

    // Integer-division thresholds: how many size-10 "slots" remain after placement
    let slots_left = post_residual / 10;
    score -= slots_left as f64 * 2.5;

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward, scaled by tightness
            let tight = (next_item_size as f64) / (post_residual as f64 + 1.0);
            score -= 12.0 + 8.0 * tight;
        } else {
            // next item cannot follow: penalize by overflow amount, with mod-class flavor
            let over = next_item_size - post_residual;
            score += over as f64 * 0.6;
            if over % 10 == 0 { score += 4.0; } // clean overflow wastes a whole class
        }
    } else {
        // last item: just minimize waste
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // New-bin candidate handling: an empty bin has full capacity
    if bin_residual == bin_capacity {
        // Prefer new bin only if no open bin fits (fitting_bins_count==0 means only this)
        // and mean residual is small; otherwise strongly discourage
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 4.0 + 6.0 * (1.0 - mean_residual / bin_capacity as f64) * (0.5 + progress);
        score -= new_bin_bonus;
        if fitting_bins_count > 1 {
            score += 15.0; // other bins fit; opening new bin is wasteful
        }
        // dead-space class check: an empty bin is always "clean", slight edge
        score -= 1.0;
    } else {
        // Prefer bins whose residual is close to the item (tight fits)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
        // reward using bins far from empty (consolidation)
        if bin_residual < bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // Harmonic coupling: item class vs post_residual class agreement
    let item_class = item_size / 10;
    let post_class = post_residual / 10;
    if item_class == post_class && post_residual > 0 {
        score -= 2.0; // same harmonic class: future similar items likely fit
    }

    // Mild pressure to keep number of open bins low
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size.max(1) as f64;

    // Base: quadratic coupling of post_residual with stream progress.
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Strong exact-fit rewards (borrowed and tuned): exact match of post
    // residual to next item is a perfect two-step fill.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 470.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 75.0 * (1.0 - next_post as f64 / cap);
            if next_post == 0 {
                score -= 45.0;
            } else if next_post < 12 {
                score += 15.0;
            }
            // Future reusability: residual that still fits half-size items.
            if next_post >= 10 && (next_post as f64) >= nxt * 0.5 {
                score -= 9.0 * (1.0 - next_post as f64 / cap);
            }
            if (next_post as f64) >= nxt {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            // This placement strands the residual below next item size:
            // penalize proportionally to the gap (quadratic waste ratio).
            let gap = (next_item_size - post_residual) as f64;
            let waste_ratio = gap / nxt;
            score += 0.65 * gap.min(25.0) + 6.0 * waste_ratio * waste_ratio * (1.0 - progress);
            if fitting_bins_count <= 2 {
                score += 11.0 * (1.0 - progress);
            }
        }
    }

    // Penalize tiny unusable residuals with a smooth rational term.
    score += 4.0 / (1.0 + pr * pr / 25.0) * (1.0 - progress * 0.3);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 2.5 * last_chance * (0.5 + 0.5 * progress);

    // Compactness pressure toward below-mean residuals.
    let dev = mean_residual - pr;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    // Mild penalty on bin proliferation early in the stream.
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate handling: open a new bin only for large items early,
    // or when open bins would strand significant dead space.
    if bin_residual == bin_capacity {
        let fill_ratio = item / cap;
        score -= 11.0 * (1.0 - fill_ratio) * (1.0 - progress * 0.5);
        if open_bins_count > 1 && item < nxt {
            score += 6.0;
        }
        if item >= 0.9 * nxt.max(1.0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Avoid opening new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 1 && fill_ratio < 0.7 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
