pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gaps that are too small for even the smallest plausible item are dead space.
        let min_useful_gap = 10.0_f64.min(next_item_size as f64).max(1.0);
        if (post_residual as f64) < min_useful_gap {
            score += 60.0;
        } else {
            // Non-linear penalty: tiny usable gaps still waste space.
            let gap_frac = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * (1.0 - gap_frac) * (1.0 - gap_frac);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post-residual can't hold the next item (wasted pairing potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins over opening new ones.
    let pressure = (open_bins_count as f64) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when the item fits elsewhere.
        score += 35.0 + pressure;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).sqrt();
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid opening a new bin.
        score -= 25.0;
    }

    // Prefer bins whose residual is above the mean (balance residual distribution).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Late in the stream, tighten up: waste less on small-gap preferences.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the post residual exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near-perfect 2-step matches: next item leaves a small unusable gap.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain gets bonus; small gaps still mildly rewarded.
        score -= 40.0 * (-gap / 12.0).exp();
    }

    // Penalize residuals that cannot fit the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.5 * deficit;
    }

    // Penalize large post residuals relative to the mean residual across open bins
    // (wasting a roomy bin when tighter ones exist).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when many bins are already open,
    // encouraging consolidation; relax slightly as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
    }

    // Prefer tighter bins overall (small residual before placement).
    score += 0.2 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0;
    }

    // 2-step lookahead with next-post chaining.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 80.0 * (1.0 - next_post as f64 / cap);
            if next_post == 0 {
                score -= 50.0;
            } else if next_post < 12 {
                score += 15.0;
            }
            // reward if a half-size item could still use the remainder
            if next_post >= 10 && (next_post as f64) >= nis * 0.5 {
                score -= 9.0 * (1.0 - next_post as f64 / cap);
            }
        } else {
            // stranded leftover penalized by how much of next item is wasted
            let waste_ratio = (next_item_size - post_residual) as f64 / nis;
            score += 0.65 * (nis - pr).min(25.0) + 6.0 * waste_ratio * waste_ratio;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    let dev = mean_residual - pr;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0 * (1.0 - 0.5 * progress);
    }
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 11.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 10.0 + 60.0 * progress;
        // small items justify opening a fresh bin early
        score -= 11.0 * (1.0 - fill_ratio) * (1.0 - progress);
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.9 * nis.max(1.0) {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Fragmentation term: residual just under next item size is costly.
    if next_item_size > 0 && post_residual > 0 {
        let frag = pr / nis.max(1.0);
        if frag < 1.0 {
            score += 9.0 * (1.0 - frag) * (1.0 - frag) * (1.0 - progress);
        } else {
            // room for at least one more item after next: consolidation bonus
            if post_residual >= 2 * next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in the stream be conservative (avoid wasting bins),
    // later allow tighter packing priority.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin: fine, waste is minimal; small bonus instead
    } else if post_residual < 20 {
        score -= 6.0; // small gap still usable for tiny items
    } else if post_residual < 40 {
        score += 3.0; // awkward medium gap
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 14.0 + 8.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a gap that cannot fit the next item.
        score += 5.0 * (1.0 - progress);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let waste_if_new = (bin_capacity - item_size) as f64;
        score = waste_if_new + 30.0;
        // Late in stream with many open bins, prefer consolidating: penalize new bins more.
        score += 15.0 * progress + 0.5 * open_bins_count as f64;
        // But if mean residual is high (open bins are crowded/fragmented), a new bin is okay.
        score -= 0.15 * mean_residual;
        // If the next item is large and would need a fresh bin anyway, soften penalty.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Global state coupling: when many bins are open, favor filling existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // Prefer bins whose residual deviates from mean in a useful way (below mean = tighter bin).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild time-horizon shaping: as stream ends, prioritize perfect closures.
    if post_residual == 0 {
        score -= 30.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: reward small post-residual, with non-linear coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth penalty for awkward dead space (post_residual too small to be useful).
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead;

    // Reward tight fits: item filling most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill;

    // Lookahead coupling: prefer post_residual close to next item size.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.25 * gap;
        score -= 10.0 * (-((pr - next_item_size as f64).powi(2)) / 200.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += 0.1 * (pr - mean_residual).abs();

    // Smooth penalty for leaving residual that matches common item sizes poorly.
    let harm = (pr / 10.0).sin().abs();
    score += 3.0 * harm * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let mut score = post_residual as f64;

    score += 0.3 * ((pr - mean_residual) / cap);

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0;
    } else if post_residual % 10 == 0 {
        score -= 14.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    if next_item_size > 0 {
        if pr >= nis {
            let next_post = post_residual - next_item_size;
            score -= 75.0 * (1.0 - next_post / cap);
            if next_post == 0 {
                score -= 45.0;
            } else if next_post < 12 {
                score += 15.0;
            }
            if next_post as f64 >= nis * 0.5 && next_post >= 10 {
                score -= 9.0 * (1.0 - next_post as f64 / cap);
            }
            if next_post as u32 >= 2 * next_item_size {
                score -= 6.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
            }
        } else {
            score += 8.0 + 0.65 * (nis - pr).min(25.0);
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 24.0 * (1.0 - progress);
            let waste_ratio = (next_item_size - post_residual) as f64 / nis;
            score += 6.0 * waste_ratio * waste_ratio;
        }
        if pr == nis {
            score -= 470.0;
        }
    }

    let frac = pr / cap;
    if frac > 0.5 {
        score -= 5.0;
    } else if frac < 0.2 {
        score += 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 11.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 11.0 * (1.0 - fill_ratio);
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        if item_size as f64 >= 0.9 * nis.max(1.0) {
            score -= 8.0 * (1.0 - progress);
        }
        score += open_bins_count as f64 * 1.2 + progress * 8.0;
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    let dev = pr - mean_residual;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let reuse = (post_residual - next_item_size) as f64 / cap;
        score -= 5.5 * (1.0 - reuse);
    }

    let frag = if next_item_size > 0 { pr / nis.max(1.0) } else { 0.0 };
    if frag > 0.0 && frag < 1.0 {
        score += 9.0 * (1.0 - frag) * (1.0 - frag) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual in low modulo classes of 10 is more reusable.
    let pr = post_residual;
    let class = pr % 10;
    score -= (10 - class) as f64 * 2.0; // residuals ending near 9 are "harmonic" (pair with 10k+1.. items)

    // Dead space penalty: small unusable residuals (below min item size 1..10 band).
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr >= 10 && pr < 25 {
        score += 15.0;
    }

    // Reward bins whose residual matches next item size well (lookahead pairing).
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).unsigned_abs() as f64;
        if next_item_size <= pr {
            score -= 40.0 - gap.min(40.0); // next item fits this bin afterwards
        } else {
            score += 10.0;
        }
        // Perfect two-item packing: post_residual == next_item_size exactly.
        if pr == next_item_size {
            score -= 120.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open new bin
        }
        // Late in stream, prefer closing out open bins instead of new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 80.0;
    }

    // Prefer fuller bins: compare residual to mean residual across open bins.
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Integer-division threshold: bins with residual >= 50 are "half-full class" —
    // keep them flexible for medium items.
    if pr >= 50 {
        score += 8.0;
    }

