        if lookahead_gap < 0.5 {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits here: mild reward proportional to tightness
            score -= 15.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // next item would NOT fit here: penalize leaving a stranded gap
            score += 12.0 + 0.15 * lookahead_gap;
