        if (item_size as f64) >= 0.9 * nis {
            score -= 8.0 * (1.0 - progress);
        }
        // don't open a new bin when mean residual across open bins can still absorb items
        if mean_residual > nis * 1.5 && progress > 0.3 {
            score += 12.0;
        }
    }

    // Dead-space penalty when the leftover cannot serve the next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < nis {
        score += post_residual as f64;
        score += 24.0 * (1.0 - progress);
    }

    // Bonus for bins that can be reused by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 13.0 + (post_residual - next_item_size) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize wasted residual, but weight it non-linearly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth interaction: tight fits (low post_residual) are rewarded more as stream advances.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize bins whose residual deviates strongly from the mean residual (imbalance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: reward if next item fits smoothly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack) * (0.4 + 0.6 * progress);
        } else {
            // Next item won't fit: penalize small post_residual (dead space risk).
            score += 10.0 * (1.0 - norm_pr);
        }
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
