pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional class of post_residual relative to capacity (harmonic classes: 1/4, 1/2, 3/4)
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward tight fits: residual in small harmonic classes is fine only if next item can use it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt as u32 <= post_residual {
            // Next item fits here: strong reward for chaining
            let chain_fit = (post_residual as f64 - nxt) / cap;
            score -= 12.0 * (1.0 - chain_fit); // prefer exact chaining
        } else {
            // Next item cannot use leftover: penalize dead space, more so in mid classes
            score += 8.0 * frac;
            // Harmonic penalty: leftover in (0,25%) is nearly dead space
            if frac < 0.25 {
                score += 15.0 * (0.25 - frac);
            }
        }
    } else {
        // Last item: simply minimize leftover
        score -= 5.0 * (1.0 - frac);
    }

    // Integer-division thresholds on post_residual: multiples of 10 are "usable" slots
    let decile = post_residual / 10;
    let decile_rem = post_residual % 10;
    if decile_rem == 0 && post_residual > 0 {
        score -= 4.0; // clean decile residual is reusable
    } else {
        score += decile_rem as f64 * 0.6;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: mildly prefer bins where item fills a larger fraction
        score -= 3.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // New-bin candidate: opening a bin is only good when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // penalize opening when open bins have plenty of room; reward when residuals are fragmented
        score += 25.0 * pressure;
        if next_item_size > 0 && (next_item_size as u32) > (mean_residual as u32).min(bin_capacity) {
            score -= 10.0; // fragmentation ahead: fresh bin sensible
        }
        if post_residual as f64 >= item_size as f64 {
            score -= 2.0;
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * frac;

