    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Odd leftovers are harder to fill: mild penalty.
    if pr % 2 == 1 && pr > 0 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let nxt_class = (pr - next_item_size) / 10;
            score -= (4.0 - nxt_class as f64).max(0.0) * 2.0;
        } else {
