    // New-bin candidate handling: prefer opening a new bin only when all
    // open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: slightly above a mediocre fit.
        score = cap * 0.55;
        // Early in the stream, opening bins is cheap (builds a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // If many open bins already, discourage proliferation.
        score += open_bins_count as f64 * 1.5;
        // Large incoming items favor fresh bins.
        score -= (item_size as f64 / cap) * 10.0;
    } else {
        // Reward tight fits relative to current mean residual across bins.
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= tightness * 10.0;
        // Spread-awareness: if this bin's residual is far below the mean,
        // it is a "small" bin best consumed now.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Check if the leftover gap could still fit the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // gap stays usable for next item
        } else if post_residual > 0 {
            score += 15.0; // gap too small for the next item -> dead space
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of open bins,
    // scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    // Relative fit quality: favor bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 50.0;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: mildly penalized so it's chosen only when
    // open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize leaving residual that can't hold the next item (dead space risk).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits here later; slight bonus for tight coupling.
            score -= 0.10 * next_item_size as f64;
        }
    }

    // Compare against mean residual: prefer bins whose post-residual is near/below average
    // (concentrate waste rather than spreading it).
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave large unusable residue.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 0.9 + 5.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 12.0;
        }
    }

    // Tight fits are always good: reward low post_residual nonlinearly.
    score -= 20.0 * ((1.0 - post_residual as f64 / bin_capacity as f64)).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively for large items.
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    score += tight_bonus;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: penalize if the next item would fit poorly in the post-residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item cannot follow here; mild penalty proportional to wasted opportunity.
            score += 8.0;
        } else {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3;
            // Bonus if next item fits snugly too.
            if gap < 5.0 {
                score -= 12.0;
            }
        }
    }

    // Time horizon: early in stream, prefer filling existing bins less aggressively
    // (keep options open); late in stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * (open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5));

    // Penalize bins whose residual deviates far above mean (fragmentation signal).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // New-bin candidate: only attractive when no open bin fits well or stream is late
    // and residuals are low overall.
    if bin_residual == bin_capacity {
        let good_open_exists = mean_residual > item_size as f64 * 1.3 && fitting_bins_count > 0;
        if good_open_exists && progress < 0.85 {
            score += 55.0;
        } else {
            score += 15.0;
        }
        // Late stream with tiny mean residual: opening fresh bin is fine.
        if mean_residual < 20.0 {
            score -= 25.0;
        }
    }

    // Slight preference for larger items into larger-residual bins.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 60.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // 2-step lookahead with chained-fit rewards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 80.0 * (1.0 - next_post as f64 / cap);
            if next_post == 0 {
                score -= 50.0;
            } else if next_post < 12 {
                score += 15.0;
            }
            // room for a third item
            if next_post >= nis * 0.5 && next_post >= 10 {
                score -= 8.0 * (1.0 - progress);
            }
        } else {
            // next item cannot use this leftover: penalize stranded space
            let stranded = (nis - pr).min(30.0);
            score += 0.7 * stranded;
            score += 20.0 * (1.0 - progress);
            let waste_ratio = stranded / nis;
            score += 6.0 * waste_ratio * waste_ratio;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let dev = mean_residual - pr;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
        if post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 10.0 + 60.0 * progress;
        score -= 11.0 * (1.0 - fill_ratio);
        if open_bins_count > 1 && item_size < next_item_size {
            score += 6.0;
        }
        if item_size as f64 >= 0.9 * nis {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Fragmentation term.
    let frag = pr / nis;
    if frag > 0.0 && frag < 1.0 {
        score += 9.0 * (1.0 - frag) * (1.0 - frag) * (1.0 - progress);
    }

    // Late stream: consolidate.
    if progress > 0.7 && post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (bins will close anyway); late, waste is costly.
    let progress_coupling = norm_pr * norm_pr * (0.5 + progress) * cap;
    score += 0.8 * progress_coupling;

    // Reward near-full bins more aggressively as stream advances.
    let tightness = (cap - pr) / cap;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 10.0;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) as f64;
        let unusable = gap / cap;
        score += 15.0 * unusable * unusable * (1.0 + progress);

        // Reward leaving exactly enough room for the next item (chained fit).
        let chain = if pr >= nx {
            1.0 - ((pr - nx) / cap)
        } else {
            0.0
        };
        score -= 12.0 * chain * chain * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild pressure toward consolidating many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Prefer bins whose residual is close to the mean residual (balance).
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of 10, or large enough for typical items) are favored.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Exact decade residuals are perfectly reusable -> strong reward.
        if class == 0 {
            score -= 12.0;
        } else if class <= 2 {
            score += 6.0; // near-decade slivers are dead space
        }
        // Integer-division thresholds: can it hold a mid-size item (>= 30)?
        if pr >= 30 {
            score -= 4.0;
        } else if pr < 10 {
            score += 8.0; // unusable dead space penalty
        }
    } else {
        // Perfect closure of a bin is ideal.
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (pr as f64) >= n && pr > 0 {
            // Harmonic match: leftover divisible-ish by next item size.
            if pr % (next_item_size.max(1)) == 0 {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Leftover too small for the next item -> penalize proportionally.
            score += 3.0 + (n - pr as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + (post_residual as f64) * 0.1;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the fit into open bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a bin early in the stream (more future items to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins already open and mean residual is fragmented, discourage.
        score += (open_bins_count as f64) * 1.5 + (mean_residual - cap * 0.5).max(0.0) * 0.2;
        // Big items justify fresh bins.
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild tight-fit reward: small post_residual relative to item means good fill.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / cap;
        score -= fill_ratio * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
