    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 - progress * 5.0;

    // Penalize opening a brand-new bin when decent alternatives exist
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
