        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (residuals that many typical item sizes can still fill).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Modulo arithmetic on post_residual: classify into harmonic buckets.
    // Residuals divisible by 10 or 20 are "harmonic" and pair well with
    // items of size 10..80; reward them.
    let harmonic = (post_residual % 20 == 0) as f64 * 6.0
        + (post_residual % 10 == 0) as f64 * 3.0
        + (post_residual % 25 == 0) as f64 * 4.0;

    // Dead-space penalty: small nonzero residuals are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Very tight fit (post_residual tiny relative to item) is excellent.
    if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this residual: penalize leaving large residuals
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tighter bins overall (smaller residual before placement).
    score += 0.10 * (bin_residual as f64 - pr);

    // Encourage closing in on capacity: reward near-full placements.
    score -= harmonic;

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits (large post_residual or many open bins already).
    if bin_residual == bin_capacity {
        // mild baseline so it competes; scales with stream progression
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.45 + 10.0 * progress + 0.02 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.05 * next_item_size as f64;
        }
    }

    // Small mean-residual coupling: when open bins are already tight,
    // slightly prefer filling them rather than spreading.
    if mean_residual < 0.35 * cap {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact-fill rewards (strongest)
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 470.0 + 18.0 * (1.0 - progress);
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 75.0 * (1.0 - next_post / cap);
            if next_post < 12 {
                score += 15.0;
            }
            if next_post == 0 {
                score -= 45.0;
            }
            // reward leaving room for a possible second future fit
            if next_post >= next_item_size.max(1) {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let stranded = pr;
            if stranded < nis {
                let waste_ratio = (next_item_size - post_residual) as f64 / nis;
                score += 0.65 * (nis - stranded).min(25.0)
                    + 6.0 * waste_ratio * waste_ratio
                    + 24.0 * (1.0 - progress);
            }
        }
    }

    // Dead-space penalty for residual too small for next item
    let dead = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        post_residual as f64
    } else {
        0.0
    };
    score += 1.0 * dead;

    // Mean-residual alignment
    let dev = mean_residual - pr;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 11.0 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 11.0 * (1.0 - fill_ratio);
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.9 * nis.max(1.0) {
            score -= 8.0 * (1.0 - progress);
        }
        score += 10.0 + 60.0 * progress;
    }

    // Fragmentation quadratic term
    let frag = if next_item_size > 0 { pr / nis.max(1.0) } else { 0.0 };
    if frag > 0.0 && frag < 1.0 {
        score += 9.0 * (1.0 - frag) * (1.0 - frag) * (1.0 - progress);
    }

    score * 0.95 + nis * 0.05
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
