pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavy penalty for small unusable gaps.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(3.0) * 400.0;
        score += dead;
        // Gap too small for typical minimum item => strong dead-space penalty.
        if post_residual < 10 {
            score += 250.0;
        }
    } else {
        // Perfect fit reward.
        score -= 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit in the leftover: penalize creating stranded gap.
        score += 40.0;
    }

    // Prefer filling bins with larger residual (reduce fragmentation across fleet).
    score += (mean_residual - bin_residual as f64).abs() * 0.5;

    // New-bin candidate: mildly discouraged unless current fits are all poor.
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer a fresh bin only when the current item leaves a residual
        // that matches the next item well, or when fits are scarce.
        let lookahead_fit = if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            -30.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64)
        } else {
            0.0
        };
        let scarcity = if fitting_bins_count <= 1 { -25.0 } else { 15.0 * fitting_bins_count as f64 };
        // Opening a new bin early in the stream is cheap; late it is wasteful.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let progress_penalty = 40.0 * progress;
        return post_residual as f64 + lookahead_fit + scarcity + progress_penalty;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual == next_item_size -> strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as f64) >= next_item_size as f64 {
            // Next item still fits: reward closeness to exact match.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize tight leftovers that
            // become dead space, scaled by how badly it misses.
            let miss = next_item_size as f64 - post_residual as f64;
            score += 10.0 + 25.0 * (miss / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 5.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual far below the mean are "odd-sized"; using them
    // for this item is fine if it tightens them, bad if it leaves junk.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Leaves bin below average residual: slightly penalize unless very tight.
        score += 0.15 * (-dev);
    } else {
        // Leaves bin above average: mild reward for preserving slack balance.
        score -= 0.05 * dev;
    }

    // --- Last-chance bonus: only this bin fits, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // --- Tight fit reward ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual < 10 {
        score -= 12.0;
    }

    // Mild penalty for spreading across too many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness); // perfect fit gets big bonus

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // wasted residual below next item size
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // residual that can host next item is valuable
            score -= 0.25 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when existing
    // bins are very full (poor fits) or many bins are already open.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        let mut new_bin_cost = 18.0;
        // early in stream, keep bins open to consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 10.0 * progress; // later in stream, new bins cheaper
        // if mean residual is high, existing bins have room; discourage new bin
        new_bin_cost += 0.3 * mean_residual;
        // many open bins: consolidation pressure
        new_bin_cost += 0.5 * open_bins_count as f64;
        // if item is large relative to mean residual, existing fits are poor
        let poor_fit = (item_size as f64 - mean_residual).max(0.0);
        new_bin_cost -= 0.8 * poor_fit;
        score += new_bin_cost;
    }

    // Slight preference for filling fuller bins (larger residual use).
    score += 0.1 * (bin_residual as f64 - post_residual as f64).max(0.0) * 0.0; // neutral placeholder
    score -= 0.05 * (bin_capacity - bin_residual) as f64; // favor already-filled bins

    // Non-linear penalty on very small post_residual that is still unusable
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
