pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * (1.0 - progress);

    let mut score = post + 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            score += 8.0 * (1.0 - (post / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (0.5 + progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep neutral baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
