pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: penalize "dead" classes
    let cls = post_residual % 10;
    let dead_penalty = match cls {
        1..=4 => 6.0,   // slivers almost unusable
        5 => 2.0,       // half-sliver, occasionally useful
        6..=9 => -2.0,  // chunky residuals still placeable
        _ => -1.0,      // exact multiples of 10 are great
    };
    score += dead_penalty;

    // Reward small post_residual (tight fit), with non-linear emphasis
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 8.0 - gap as f64 * 0.4;
            } else {
                score += (gap as f64) * 0.15;
            }
        } else {
            // next item can't use this bin's remainder; small penalty scaled by waste
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize unless residual is very tight or item huge
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.8 {
            score -= 10.0; // big item: fresh bin is fine
        } else {
            score += 14.0 + 20.0 * (1.0 - tightness); // prefer existing bins
        }
    }

    // Prefer filling bins with low residual relative to mean (balance consolidation)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in stream: consolidate aggressively into fewest bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold: residual divisible into two useful halves
    if post_residual >= 20 && post_residual % 2 == 0 && post_residual / 2 >= 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Zero residual (perfect fill) is ideal: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (low waste ratio).
    if bin_residual > 0 {
        score += 0.5 * (item_size as f64 / bin_residual as f64) * 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post-fit residual is dead space).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 10 && post_residual > 0 {
            score += 30.0; // override: dead space outweighs last-chance savings
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean:
    // bins below mean residual are "tighter", good targets.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead (k=2): if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item nearly-but-not-exactly fits,
    // which would strand awkward space.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: empty bin has huge residual; make it
    // attractive only when no good fit exists. Default: mildly unattractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * open_bins_count as f64;
        // If the item is large (>= half capacity), opening fresh is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If the next item is huge and current item is small, keep fresh bin
        // available for the big one later: penalize wasting it now.
        if next_item_size >= 70 && item_size <= 30 {
            score += 25.0;
        }
    }

    // Late in the stream: consolidate aggressively to avoid leftover bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
