    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Next item fits here afterwards: reward tight chained fit.
            let chain_waste = post - next;
            score -= 60.0 * (1.0 - chain_waste / bin_capacity as f64);
            if chain_waste == 0.0 {
                score -= 80.0; // perfect 2-chain
            }
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += 0.5 * (next - post).min(post);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving large unusable fragments (below minimum item size 1..100 range heuristic).
    let frag = post_residual as f64;
    if frag > 0.0 && frag < 10.0 {
        score += 40.0 * (1.0 - frag / 10.0);
    }

    // Prefer filling nearly-full bins harder as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size.max(10) && next_item_size > 0 {
        score += 8.0; // residual likely unusable for the next item
    }

    // Lookahead coupling: reward residuals that still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative about filling bins;
    // later, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with slack -> prefer bins below mean residual
    // (consolidate slack); few open bins -> spread load.
    let dev = post_residual as f64 - mean_residual;
    if open_bins_count > 4 {
        score -= 0.15 * dev;
    } else {
        score += 0.10 * dev;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere else (empty bin has post_residual == capacity - item_size).
    if bin_residual == bin_capacity {
        let slack = bin_capacity - item_size;
        score += 20.0 + 0.3 * slack as f64;
        if fitting_bins_count >= 1 {
            score += 15.0; // some open bin fits, so avoid new bin
        }
        if progress > 0.8 {
            score -= 10.0; // late stream: new bins cheaper than fragmentation
        }
    }

    score
}

