pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small divisor classes" of the capacity are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are nice harmonic fractions of capacity.
        let cap_f = bin_capacity as f64;
        let pr_f = pr as f64;
        let frac = pr_f / cap_f;
        if (pr % 50) == 0 {
            score -= 12.0; // half-capacity class: extremely reusable
        } else if (pr % 25) == 0 {
            score -= 8.0;  // quarter class
        } else if (pr % 10) == 0 {
            score -= 5.0;  // decade class
        } else if pr <= 10 {
            score += 15.0; // dead space penalty: tiny residual unusable
        }
