    let class_bonus = match class {
        0 => -12.0,          // perfectly tight residual
        1..=5 => -6.0,       // near-tight
        6..=9 => 4.0,        // awkward dead space
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division threshold: residual bands by capacity fraction.
    let frac = post_residual as f64 / cap;
    if frac <= 0.05 {
        score -= 10.0;
    } else if frac <= 0.15 {
        score -= 4.0;
    } else if frac >= 0.5 {
        score += 8.0; // leaving half a bin empty is wasteful
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack % 10 == 0 {
            score -= 9.0;
        } else if slack <= 5 {
            score -= 5.0;
        } else {
            score += slack as f64 * 0.05;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize mildly unless this is a last-chance bin
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave huge waste
    // or the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let waste_elsewhere = post_residual as f64;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / cap).max(0.1);
        score = cap * 0.35 + waste_elsewhere * 0.3 + pressure * 2.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // fresh bin guarantees hosting the next item too
        }
    }

    // Progression: tighten criteria late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 4 {
        score -= 70.0 + 7.0 * (4 - post_residual) as f64;
    } else if post_residual < 10 {
        score -= 14.0;
    }

    // 2-step lookahead with next-post slack shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 470.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 75.0 * (1.0 - next_post as f64 / cap);
            if next_post < 12 {
                score += 15.0;
            }
            if next_post == 0 {
                score -= 45.0;
            }
            // future reusability: next_post can host the next item again
            if next_post as u32 >= next_item_size {
                score -= 9.0 * (1.0 - next_post as f64 / cap);
            }
        } else {
            // dead space: stranded gap penalized proportionally
            let stranded = pr;
            score += 0.65 * (nis - stranded).min(25.0);
            let waste_ratio = (next_item_size - post_residual) as f64 / nis;
            score += 6.0 * waste_ratio * waste_ratio;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let dev = mean_residual - pr;
    score += 0.3 * dev;
    if dev.abs() > 40.0 {
        score += 3.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 11.0 * (1.0 - progress);
    }

    // New-bin candidate handling: penalize as stream progresses, but allow
    // opening fresh bins early for large items that would strand small gaps.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 10.0 + 60.0 * progress;
        score -= 11.0 * (1.0 - fill_ratio) * (1.0 - progress);
        if open_bins_count > 1 && item_size < next_item_size.max(1) {
            score += 6.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.9 * nis.max(1.0) {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Fragmentation guard: residual too small relative to next item.
    if next_item_size > 0 && pr > 0.0 && pr < nis {
        let frag = pr / nis;
        score += 9.0 * (1.0 - frag) * (1.0 - frag) * (1.0 - progress);
        score += 24.0 * (1.0 - progress);
        score += 1.0 * pr;
    }

    // Roomy residuals that can host two more next-sized items.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space (nothing can ever fit in it).
            score += 60.0;
        } else if post_residual <= 20 {
            // Only tiny items (rare) could fit here.
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 50.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: avoid opening a new bin if this is the only option.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the empty new-bin candidate).
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to existing open bins,
        // but allow it when item is large and would leave a useful residual.
        score += 15.0 + 2.0 * pressure;
        if item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Slight bonus for using existing bins, scaled by pressure.
        score -= (pressure / (pressure + 5.0)) * 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: penalize leftover more.
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (consolidate space in few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early stream: be a bit more willing to open bins (diversity),
    // late stream: squeeze everything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < item_size.min(50) {
        score += 12.0; // awkward leftover
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted fit chance.
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, prefer tighter packing since fewer future items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage filling them.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when it enables a near-perfect future fit
    // or when open bins are nearly exhausted of useful space.
    if bin_residual == bin_capacity {
        let new_bin_base = 30.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) == post_residual as i64 {
            score -= 55.0; // reserve fresh bin for next item pairing
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
        score += new_bin_base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize leftover space, with a smooth non-linear polynomial in normalized post-residual.
    // Small residuals are good (low score); large residuals get quadratically/cubically penalized.
    let mut score = x * (1.0 + 1.5 * x + 1.2 * x * x);

    // Stream-progress coupling: later in the stream, leftover space becomes harder to fill,
    // so amplify the penalty on large residuals as progress -> 1.
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += (1.0 - prog_coupling) * 2.0 * x * x;

    // Perfect fit reward: strongly subtract when post_residual is tiny.
    if x < 0.1 {
        score -= (0.1 - x) * 20.0;
    }

    // Lookahead coupling: reward bins whose residual can still fit the next item smoothly.
    let n = next_item_size as f64;
    if n > 0.0 {
        let fits_next = (pr >= n) as i32 as f64;
        let tight_next = (1.0 - ((pr - n) / cap).abs()).max(0.0);
        score -= fits_next * (0.5 + progress) * tight_next;
        // Penalize if this placement blocks the next item (residual too small for lookahead).
        let blocked = (pr < n && pr > 0.0) as i32 as f64;
        score += blocked * 1.5 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * (1.0 - x);
    }

    // Mean-residual coupling: prefer bins whose residual differs from the mean in a
    // non-linear way — filling bins far below the mean residual consolidates space.
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev.abs();

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish baseline so it wins only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 1.2 + 1.5 * x + progress * 0.8 - (fitting_bins_count == 0) as i32 as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes mod 10.
    let class = post_residual % 10;
    // Residuals that are "harmonically useful" (small, likely fillable by small items)
    // get a bonus; mid-range dead space is penalized super-linearly.
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward
    } else if post_residual <= 10 {
        score -= 8.0 + (10 - post_residual) as f64;
    } else if post_residual <= 30 {
        // dead-space zone: penalize with quadratic growth
        score += (post_residual as f64 - 10.0) * 0.9;
    } else {
        // large residual is still usable; mild penalty
        score += 18.0 + (post_residual as f64 - 30.0) * 0.15;
    }

    // Class-based coupling: even classes of residual pair better with even next items.
    if next_item_size > 0 && post_residual >= next_item_size {
        // lookahead fits: reward
        let slack = post_residual - next_item_size;
        score -= 6.0 + slack as f64 * 0.1;
        if (post_residual % 2) == (next_item_size % 2) {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize by overflow size
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Integer-division threshold on bin fill fraction (harmonic capacity fractions).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let k = (fill * 4.0) as u32; // quarter classes
    score -= match k {
        0 => 0.0,
        1 => 3.0,
        2 => 7.0,
        3 => 12.0,
        _ => 18.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when all open bins are nearly full
    // or the current item leaves a bad class of dead space in existing bins.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = if avg_open > 0.0 { item_size as f64 / avg_open } else { 0.0 };
        // open new bin when existing residuals are tight relative to item
        score += 30.0 - pressure * 25.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0; // fresh bin helps the lookahead too
        }
    }

    // Progress coupling: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Mean-residual coupling: if this bin is far below mean residual, it's underused.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is smaller than the smallest plausible item (1)
    // but practically, gaps below ~20 are hard to fill; scale penalty by gap size.
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            // Penalize small gaps quadratically to strongly avoid creating them.
            score += (dead_threshold - post_residual as f64).powf(1.5) * 2.0;
        }
        // Perfect fits (zero waste) get a strong reward.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward tight fits: relative fill ratio bonus.
    let fill = (item_size as f64) / (bin_residual as f64);
    score -= fill * 15.0;

    // Open bins pressure: with many open bins, prefer reusing existing bins
    // (especially the new-bin candidate should look unattractive then).
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins.
        score += pressure * 3.0;
    } else {
        // Existing bin: mild reward to prefer reuse over opening new bins.
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Next item won't fit in the gap: penalize leaving a gap next item can't use.
        score += 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a tight bin worth filling; if far above mean, deprioritize slightly.
    let resid_diff = (bin_residual as f64) - mean_residual;
    score += resid_diff * 0.1;

    // Stream progression: early in the stream, be slightly more willing to open
    // new bins (flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
