pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits exactly: strong reward.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted chain opportunity,
            // worse when the gap is small (almost-fit is most wasteful).
            score += 8.0 + 12.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Penalize small dead space that no future item (>=1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current bins are quite full
    // or nothing fits well; keep it mildly penalized otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = bin_capacity as f64 - mean_residual;
        score = bin_capacity as f64 - 15.0 * avg_fill / bin_capacity as f64 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
