pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small but nonzero post-residual is good dead space.
    if post_residual > 0 {
        let tight = (20.0 - post_residual as f64).max(0.0);
        score -= 1.5 * tight;
    } else {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Penalize leaving a gap that exactly blocks typical future items
    // (post_residual slightly below the smallest possible item is dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nd {
            let gap = pr - nd;
            if gap == 0.0 {
                score -= 30.0;
            } else if gap < 10.0 {
                score -= 15.0;
            } else {
                score -= 5.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 0.3 * (nd - pr).min(80.0) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (consolidate fullness).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Discourage spreading across many open bins when few items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score += 0.2 * open_bins_count as f64;
    }

    // Mild preference for filling already-open bins vs opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, gets no tight-fit reward
    // since post_residual is large; add explicit penalty for the empty-bin case).
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - (post_residual as f64 / cap); // how full bin becomes

    // base: prefer small post_residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr / cap) - 10.0 * tight * tight;

    // stream-progress coupling: later in stream, value tight fits more
    score -= 20.0 * progress * tight * tight;

    // penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (pr - mean_residual) / cap;
    score += 8.0 * dead * dead;

    // last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tight;
    }

    // lookahead: reward residual that still fits next item, penalize otherwise
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * ((next_item_size as f64 - pr) / cap);
    }

    // mild penalty for proliferating open bins late in stream
    score += 0.05 * (open_bins_count as f64) * progress;

    // new-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

