pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "reusable" residue classes (multiples of 10) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-class bonus: leftover divisible by 10 tends to admit future
    // items from a 10..80 grid cleanly.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 20.0;
    } else {
        score += residue_class as f64; // penalize ragged leftovers
    }

    // Integer-division thresholds: classify post_residual into quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        // Dead space zone: strongly penalize small unusable leftovers,
        // unless it was an exact-ish fit already rewarded.
        score += 40.0;
    } else if post_residual <= quarter * 2 {
        score -= 10.0;
    } else if post_residual <= quarter * 3 {
        score -= 15.0;
    }

    // Harmonic coupling with next item (k=2 lookahead):
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item -> chain bonus.
            let chain_gap = post_residual - next_item_size;
            score -= 25.0;
            score -= (chain_gap % 10) as f64;
            if chain_gap == 0 {
                score -= 60.0; // perfect two-item chain
            }
        } else {
            // Leftover cannot fit the lookahead item: penalize proportionally.
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.5;
            // If leftover is tiny relative to next item, it is dead space.
            if post_residual < 10 {
                score += 30.0;
            }
        }
    } else {
        // Last item: minimize leftover, prefer any fitting bin.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Give it a baseline near "half-wasted" so tight
    // fits in open bins beat it, but bad fits do not.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (mean_residual * 0.1);
        // Early in the stream, or when many items remain, opening fresh bins
        // is cheaper (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= next_item_size as f64 * 0.2;
        }
    }

    // Mild pressure against bin sprawl: with many open bins, prefer consolidation.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Tie-break: prefer bins whose residual is closest to the mean (balance).
    score += ((pr - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 {
        // Residual large enough to be reusable: mild reward scaled by size.
        score -= 0.15 * (post_residual as f64).min(40.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // (favor bins with small residual relative to the mean).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * (bin_residual as f64 - mean_residual) * 0.05;

    // Lookahead: if next item fits snugly into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0 * (10.0 - slack as f64);
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins from being opened frivolously;
        // reduced when the current item is large (poor fit anywhere).
        let large_item_bonus = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        score += 30.0 - large_item_bonus;
        // If the next item is large, opening a fresh bin now may be wise.
        if next_item_size >= 60 && item_size >= 40 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fits are highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can also fit here: reward tightness of the match.
            score -= (30.0 - diff).max(0.0) * 4.0;
            // Bonus for a perfect two-item fill.
            if diff == 0.0 {
                score -= 200.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space
            // proportionally to how much of the next item is wasted.
            let wasted = nxt - post_residual as f64;
            score += wasted * 1.5;
        }
    }

    // Prefer bins with residual below the mean residual (tighter bins),
    // keeping loose bins available for larger future items.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let has_good_fit = fitting_bins_count > 0 && post_residual == bin_capacity as u32;
        if has_good_fit {
            // There are fitting bins; discourage opening a new one unless
            // the current item is large relative to capacity.
            score += if item_size as f64 > 0.7 * bin_capacity as f64 { 50.0 } else { 400.0 };
        } else {
            // No fitting bins elsewhere: new bin is the natural choice.
            score -= 150.0;
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}
